code.text:
resource "aws_launch_template" "sandbox" {
  for_each = var.sizes # { lite = "m8i.xlarge", full = "m8i.2xlarge", wide = "m8i.4xlarge" }

  name          = "${var.name_prefix}-sandbox-${each.key}"
  image_id      = "resolve:ssm:/ai-agents/sandbox/ami-id" # promoted by the nightly smoke test (G3-16)
  instance_type = each.value

  iam_instance_profile { name = aws_iam_instance_profile.sandbox.name } # SSM core only
  vpc_security_group_ids = [aws_security_group.sandbox.id]              # no ingress at all
  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1 # containers on the docker bridge can't get a token
    instance_metadata_tags      = "disabled"
  }

  block_device_mappings {
    device_name = "/dev/sda1"
    ebs {
      volume_type                = "gp3"
      volume_size                = 120
      encrypted                  = true
      kms_key_id                 = aws_kms_key.sandbox.arn
      volume_initialization_rate = 300 # MiB/s; check aws provider 6.64.0 supports this argument
    }
  }

  dynamic "tag_specifications" {
    for_each = ["instance", "volume"]
    content {
      resource_type = tag_specifications.value
      tags          = merge(var.tags, { "ai-agents:managed" = "true", "ai-agents:size" = each.key })
    }
  }
}

